package com.yeyamo_mobile.api.admin_service.event;
import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import com.yeyamo_mobile.api.admin_service.dto.PartnerReviewRequest;import com.yeyamo_mobile.api.admin_service.enums.ValidationStatus;import com.yeyamo_mobile.api.admin_service.models.PartnerValidation;import com.yeyamo_mobile.api.admin_service.repository.*;import com.yeyamo_mobile.api.admin_service.service.*;
class AdminDecisionContractTests{@Test void approvedReviewPublishesAdminEvent(){PartnerValidationRepository partners=mock(PartnerValidationRepository.class);PlaceValidationRepository places=mock(PlaceValidationRepository.class);AuditService audit=mock(AuditService.class);AdminEventOutbox outbox=mock(AdminEventOutbox.class);PartnerValidation v=new PartnerValidation();UUID partnerId=UUID.fromString("55555555-5555-5555-5555-555555555555");UUID adminId=UUID.fromString("66666666-6666-6666-6666-666666666666");v.setPartnerId(partnerId);when(partners.findById(v.getId())).thenReturn(Optional.of(v));when(partners.save(v)).thenReturn(v);when(audit.currentAdminId()).thenReturn(adminId);ValidationService service=new ValidationService(partners,places,audit,outbox);MockHttpServletRequest request=new MockHttpServletRequest();request.addHeader("X-Correlation-ID","req-admin");service.reviewPartner(v.getId(),new PartnerReviewRequest(ValidationStatus.APPROVED,"OK","OK",3),request);verify(outbox).partnerDecision("partner.approved",partnerId,v.getId(),"OK",3,adminId,"req-admin");}}
